  s.templates=s.templates||[['Kupní smlouva','Smlouva','2. 9. 2026'],['Rezervační smlouva','Smlouva','28. 8. 2026'],['Nabídka služeb','Nabídka','14. 8. 2026'],['Souhlas se zpracováním osobních údajů','Souhlas','1. 6. 2026'],['Předávací protokol','Ostatní','12. 5. 2026'],['Zprostředkovatelská smlouva','Smlouva','3. 4. 2026']].map(([n,t,d],i)=>({id:'tp'+i,n,t,d,on:true}));
