const SG=()=>{setSeed();return DB.settings;};
const mePref=()=>{const s=SG();s.me=s.me||{};return s.me[ME]=s.me[ME]||{};};
const orgS=()=>SG().org;
const pv=(sc,k,def)=>{const o=sc==='me'?mePref():orgS();return o[k]===undefined?def:o[k];};
const sF=(l,v)=>`<div class="field"><span class="lab">${l}</span><div class="val">${v==null||v===''?'—':v}</div></div>`;
const sn=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();

// Ovládací prvky: každá změna se uloží hned
const swI=(sc,k,def,lab,dis)=>`<span class="switch"><input type="checkbox" data-a="sset" data-on="change" data-s="${sc}" data-k="${k}" aria-label="${esc(lab)}" ${pv(sc,k,def)?'checked':''} ${dis?'disabled':''}><i></i></span>`;
const swRow=(sc,k,l,h,def=true,dis)=>`<label class="row set-row ${dis?'dis':''}"><span class="spacer">${l}${h?`<span class="small mute" style="display:block">${h}</span>`:''}</span>${swI(sc,k,def,l,dis)}</label>`;
const opt=(o,cur)=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(cur)===String(v)?'selected':''}>${esc(t)}</option>`;};
const sSel=(sc,k,l,opts,def,hint,re)=>`<div class="field"><label for="s-${k}">${l}</label><select class="inp" id="s-${k}" data-a="sset" data-on="change" data-s="${sc}" data-k="${k}" ${re?'data-r="1"':''}>${opts.map(o=>opt(o,pv(sc,k,def))).join('')}</select>${hint?`<div class="small mute set-hint">${hint}</div>`:''}</div>`;
const sInp=(sc,k,l,def,type='text',hint,extra='')=>`<div class="field"><label for="s-${k}">${l}</label><input class="inp" id="s-${k}" type="${type}" data-a="sset" data-on="change" data-s="${sc}" data-k="${k}" value="${esc(pv(sc,k,def))}" ${extra}>${hint?`<div class="small mute set-hint">${hint}</div>`:''}</div>`;
const sCard=(t,body,r='',sub='')=>`<section class="card"><div class="card-head"${sub?' style="margin-bottom:4px"':''}><h2>${t}</h2>${r?`<div class="r">${r}</div>`:''}</div>${sub?`<p class="small mute" style="margin-bottom:16px">${sub}</p>`:''}${body}</section>`;
const stBadge=on=>on?'<span class="badge b-grn">Připojeno</span>':'<span class="badge">Nepřipojeno</span>';
ACT.sset=el=>{const o=el.dataset.s==='me'?mePref():orgS(),k=el.dataset.k;o[k]=el.type==='checkbox'?el.checked:el.type==='number'?(+el.value||0):el.value.trim();save();toast('Uloženo');if(el.dataset.r)render();};

// Seznam s hledáním a stránkováním (stovky položek)
const SPS=24;
const sList=k=>ui('sp-'+k,{p:0,q:'',f:''});
function sPage(k,arr){const s=sList(k),pages=Math.max(1,Math.ceil(arr.length/SPS));if(s.p>=pages)s.p=pages-1;const from=s.p*SPS;
  return {rows:arr.slice(from,from+SPS),bar:arr.length>SPS?`<div class="set-pg"><span class="small mute">${from+1}–${Math.min(arr.length,from+SPS)} z ${arr.length}</span><button class="more" data-a="spg" data-k="${k}" data-v="-1" ${s.p?'':'disabled'} aria-label="Předchozí strana">${ic('arrow-left-2','s16')}</button><button class="more" data-a="spg" data-k="${k}" data-v="1" ${s.p>=pages-1?'disabled':''} aria-label="Další strana">${ic('arrow-right-2','s16')}</button></div>`:''};}
const sSearch=(k,ph)=>`<div class="set-search"><span class="sib">${icN('search-normal')}</span><input class="inp" id="sq-${k}" data-input="sq" data-k="${k}" value="${esc(sList(k).q)}" placeholder="${ph}" aria-label="${ph}" autocomplete="off"></div>`;
ACT.spg=el=>{sList(el.dataset.k).p+=+el.dataset.v;render();};
ACT.sq=el=>{const s=sList(el.dataset.k);s.q=el.value;s.p=0;clearTimeout(UI._sqt);const id=el.id;UI._sqt=setTimeout(()=>{render();const i=document.getElementById(id);if(i){i.focus();i.setSelectionRange(i.value.length,i.value.length);}},200);};
ACT.sfilt=el=>{const s=sList(el.dataset.k);s.f=el.dataset.v;s.p=0;render();};
const sChips=(k,vals)=>`<div class="set-chips">${vals.map(([v,l,n])=>`<button class="set-chip ${sList(k).f===v?'on':''}" data-a="sfilt" data-k="${k}" data-v="${v}" aria-pressed="${sList(k).f===v}">${esc(l)}${n!=null?` <span class="mute">${n}</span>`:''}</button>`).join('')}</div>`;
const emptyRow=(n,t='Nic nenalezeno')=>`<tr style="cursor:default"><td colspan="${n}" class="mute" style="text-align:center;height:96px">${t}</td></tr>`;
// Jednoduché okno s formulářem
function sModal(title,fields,onSave,btn='Uložit'){modal(`<h2>${title}</h2><div class="stack" style="margin-top:16px">${fields}</div><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="sm-ok">${btn}</button></div>`);document.getElementById('sm-ok').onclick=()=>{if(onSave()!==false){save();closeLayer();render();}};}
const mval=id=>(document.getElementById(id)||{}).value||'';
const mreq=id=>{const i=document.getElementById(id);if(!i.value.trim()){i.classList.add('err');i.focus();return false;}return true;};

