function secUcet(){const u=me(),p=mePref(),org=orgS(),forced=org.tfaReq==='all'||(org.tfaReq==='admins'&&(isAdmin()||isMgr()));
  const sess=p.sess||[['Chrome · Windows','Praha','Právě teď',true],['Safari · iPhone','Praha','Dnes 8:02'],['Edge · Windows','Brno','10. 9. 2026']];
  return sCard('Přihlášení',`<div class="grid g2">${sF('Přihlašovací e-mail',esc(u.email||(u.id.toLowerCase()+'@s-aver.cz')))}${sF('Heslo','Změněno 3. 6. 2026')}</div>`,`<button class="btn" data-a="spw">${ic('key','s16')}Změnit heslo</button>`)+
  sCard('Dvoufázové ověření',swRow('me','tfa','Ověřovací aplikace',forced?'Pro vaši roli je povinné, vypnout ho nejde.':'Při přihlášení z nového zařízení zadáte kód z aplikace.',true,forced))+
  sCard('Přihlášená zařízení',`<div class="tbl-card"><table class="tbl"><thead><tr><th>Zařízení</th><th>Místo</th><th>Naposledy</th><th></th></tr></thead><tbody>${sess.map((x,i)=>`<tr style="cursor:default"><td class="med">${esc(x[0])}${x[3]?' <span class="badge b-tea">Toto zařízení</span>':''}</td><td>${esc(x[1])}</td><td>${esc(x[2])}</td><td style="text-align:right">${x[3]?'':`<button class="btn" data-a="ssessout" data-i="${i}">Odhlásit</button>`}</td></tr>`).join('')}</tbody></table></div>`,sess.length>1?`<button class="btn" data-a="ssessout" data-i="all">Odhlásit všude jinde</button>`:'');}
ACT.ssessout=el=>{const p=mePref();p.sess=p.sess||[['Chrome · Windows','Praha','Právě teď',true],['Safari · iPhone','Praha','Dnes 8:02'],['Edge · Windows','Brno','10. 9. 2026']];p.sess=el.dataset.i==='all'?p.sess.filter(x=>x[3]):p.sess.filter((x,i)=>i!==+el.dataset.i);save();render();toast(el.dataset.i==='all'?'Odhlášeno na ostatních zařízeních':'Zařízení je odhlášené');};
ACT.spw=()=>{sModal('Změnit heslo',`<div class="field"><label for="pw0">Současné heslo</label><input class="inp" type="password" id="pw0"></div><div class="field"><label for="pw1">Nové heslo</label><input class="inp" type="password" id="pw1"><div class="small mute set-hint">Aspoň ${orgS().pwMin} znaků${orgS().pwMix?', číslice a symbol':''}.</div></div><div class="field"><label for="pw2">Nové heslo znovu</label><input class="inp" type="password" id="pw2"></div>`,()=>{if(!mreq('pw0'))return false;const a=mval('pw1'),b=mval('pw2'),o=orgS();const bad=(id,m)=>{const i=document.getElementById(id);i.classList.add('err');i.focus();toast(m,null,'err');return false;};if(a.length<+o.pwMin)return bad('pw1','Heslo je moc krátké.');if(o.pwMix&&!(/d/.test(a)&&/[^ws]/.test(a)))return bad('pw1','Přidejte číslici a symbol.');if(a!==b)return bad('pw2','Hesla se neshodují.');toast('Heslo je změněné');},'Změnit heslo');};

function secNotif(){const n=DB.settings.notif[ME]||{},mgrOnly=['schvaleni'];const list=NOTIFS.filter(x=>!mgrOnly.includes(x[0])||isMgr()||isAdmin());
  const on=(k,ch)=>ch==='app'?n[k]!==false:n[k+':'+ch]===true||(n[k+':'+ch]===undefined&&ch==='mail'&&['schuzka','termin','podpis','schvaleni'].includes(k));
  return `<div class="tbl-card set-mx"><table class="tbl"><thead><tr><th>Událost</th>${NCH.map(c=>`<th class="ctr">${c[1]}</th>`).join('')}</tr></thead><tbody>${list.map(([k,l])=>`<tr style="cursor:default"><td>${l}</td>${NCH.map(([ch,cl])=>`<td class="ctr"><input type="checkbox" class="cb" data-a="setnotif" data-on="change" data-k="${k}" data-ch="${ch}" aria-label="${l}: ${cl}" ${on(k,ch)?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`+
  sCard('Kdy',`<div class="grid g2">${sSel('me','digest','Souhrn e-mailem',[['0','Neposílat'],['d','Denně v 7:00'],['w','Týdně v pondělí']],'d')}</div><div style="margin-top:8px">${swRow('me','quiet','Mimo pracovní dobu neupozorňovat','Na mobil nepřijde nic mimo vaši pracovní dobu.',true)}</div>`);}
ACT.setnotif=el=>{const n=DB.settings.notif;n[ME]=n[ME]||{};n[ME][el.dataset.ch&&el.dataset.ch!=='app'?el.dataset.k+':'+el.dataset.ch:el.dataset.k]=el.checked;save();toast('Uloženo');};

