ACT.stog=el=>{const o=el.dataset.s==='me'?mePref():el.dataset.s==='integ'?SG().integ:orgS(),k=el.dataset.k;o[k]=!o[k];save();render();toast(o[k]?`${el.dataset.l}: připojeno`:`${el.dataset.l}: odpojeno`);};

function secEmail(){const u=me(),sig=pv('me','sig',`${u.name}\n${u.pos}\n${orgS().name}\n${u.phone||orgS().phone}`);
  return sCard('Odesílání',`<div class="grid g2">${sSel('me','from','Odesílat z adresy',[[u.id,(u.email||u.id.toLowerCase()+'@s-aver.cz')],['org',orgS().mail+' (společná)']],u.id)}${sSel('me','reply','Odpovědi chodí na',[['me','Mou adresu'],['org','Společnou adresu']],'me')}</div><div style="margin-top:8px">${swRow('me','mailTl','Odeslané e-maily ukládat do časové osy kontaktu','',true)}${swRow('me','mailTrack','Sledovat otevření e-mailu','Uvidíte, kdy si klient e-mail otevřel.',false)}</div>`)+
  sCard('Podpis',`<div class="grid g2"><div class="field"><label for="s-sig">Text podpisu</label><textarea class="inp" id="s-sig" rows="5" data-a="sset" data-on="change" data-s="me" data-k="sig" data-r="1">${esc(sig)}</textarea></div><div><div class="lab">Náhled</div><div class="set-sig">${esc(sig).replace(/\n/g,'<br>')}</div></div></div><div style="margin-top:8px">${swRow('me','sigReply','Vkládat podpis i do odpovědí','',true)}</div>`);}

function secApps(){const p=mePref();const A=[['appG','Google účet','Přihlášení, Gmail a kontakty.'],['appM','Microsoft 365','Přihlášení, Outlook a Teams.'],['appMob','Mobilní aplikace S-aver','Příchod do práce, notifikace a hovory z mobilu.'],['appTel','Volání z počítače','Kliknutím na číslo se hovor spustí v telefonu.']];
  return `<div class="set-int">${A.map(([k,l,h])=>`<section class="card"><div class="row" style="margin-bottom:8px"><b class="spacer">${l}</b>${stBadge(p[k])}</div><p class="small mute" style="margin-bottom:16px">${h}</p><button class="btn ${p[k]?'':'pri'}" data-a="stog" data-s="me" data-k="${k}" data-l="${l}">${p[k]?'Odpojit':'Připojit'}</button></section>`).join('')}</div>`;}

