function secOrg(){return sCard('Identifikace',`<div class="grid g3">${sInp('org','name','Název','')}${sInp('org','ico','IČO','')}${sInp('org','dic','DIČ','')}${sSel('org','obor','Obor',['Reality','Finance a pojištění','Právo','Obchod','HR','Jiné'],'Reality')}${sSel('org','cur','Měna',['CZK','EUR'],'CZK')}${sSel('org','tz','Časové pásmo',[['Europe/Prague','Praha (UTC+1)'],['Europe/Bratislava','Bratislava (UTC+1)'],['Europe/London','Londýn (UTC+0)']],'Europe/Prague')}</div>`)+
  sCard('Sídlo a kontakt',`<div class="grid g3">${sInp('org','street','Ulice a číslo','')}${sInp('org','zip','PSČ','')}${sInp('org','city','Obec','')}${sInp('org','mail','E-mail','','email')}${sInp('org','phone','Telefon','','tel')}${sInp('org','web','Web','')}</div>`)+
  sCard('Logo',`<div class="row" style="gap:16px"><span class="set-logo">${LOGO}</span><span class="small mute spacer">PNG nebo SVG, aspoň 400 px na šířku. Objeví se na dokumentech a v e-mailech.</span><button class="btn" data-a="slogo">${ic('document-upload','s16')}Nahrát logo</button></div>`);}
